"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Никсар под властью Данишмендидов — датированное свидетельство источника", "81181870"], "d": ["Источник показывает город Никсар в эту дату под управлением Данишмендидов; более раннее владение в источнике не датировано (атлас оставляет время до этой даты пустым).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["Данишмендид Гюмюштекин Гази взял Малатью", "87f1166c"], "d": ["Гюмюштекин Гази овладел Малатьей по окончании осады.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Килидж-Арслан I принял сдачу Малатьи", "eca366d5"], "d": ["После смерти Гюмюштекина Килидж-Арслан I осадой более двух месяцев присоединил Малатью к сельджукским землям.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["Мазьядид Садака погиб в Нуъмании, Хилла — к сельджукам", "e5ecea7c"], "d": ["Мухаммед Тапар победил Садаку; его сын Дубейс попал в плен, и ему не разрешили вернуться в Хиллу.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["Иларслан вернул Эльбистан у Танкреда", "923962c2"], "d": ["Эльбистан, взятый князем Антиохии Танкредом, был возвращён атабеком малатийского малика Тогрул-Арслана Иларсланом.", "ce0754bd"]},
