"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Килидж-Арслан II взял Эльбистан и Даренде", "7c109007"], "d": ["Воспользовавшись распрей между Данишмендидами, Килидж-Арслан II овладел областью Эльбистана, Даренде и Gedük.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["Рубенид Млех взял Тарс у Византии", "2f98fd11"], "d": ["Рубенид Млех при помощи Нур ад-Дина Зенги вернул у византийцев Адану, Мисис и Тарс.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["Ильдегизид Pehlivan взял Тебриз", "f0831f17"], "d": ["Ильдегизид Pehlivan мирным путём взял Тебриз у Ахмедилидов и отдал его своему брату Кызыл-Арслану.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Килидж-Арслан II взял Сивас и Никсар у Данишмендидов", "584575bb"], "d": ["После смерти Нур ад-Дина Зенги Килидж-Арслан II летом 1175 года захватил Сивас, Никсар, Токат и остальные данишмендидские земли; сивасская ветвь прекратилась.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Килидж-Арслан II взял Малатью, данишмендидская ветвь закончилась", "3bdbb060"], "d": ["После четырёхмесячной осады Малатья перешла к сельджукам, и малатийская ветвь Данишмендидов прекратилась.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Салах ад-Дин взял Амид и отдал его артукиду Нур ад-Дину Мухаммеду", "8c3cc7bb"], "d": ["Салах ад-Дин аль-Айюби осадил и взял Амид, отдал Хасанкейф артукидскому эмиру Нур ад-Дину Мухаммеду; Иналиды прекратили существование.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Рубен III вернул Адану у крестоносцев", "e9876f85"], "d": ["Мисис, Адану и Tel Hamdûn, на время перешедшие к крестоносцам после Млеха, рубенид Рубен III вернул в 1184 году.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Тикрит перешёл к Аббасидам", "e8f5aeac"], "d": ["После власти Бектегинидов город перешёл под управление Аббасидского халифата.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Рукн ад-Дин Сулейман-шах II вернул Самсун", "0971ebcd"], "d": ["Самсун и восточночерноморские земли, перешедшие к Комнинам во время братских распрей, были возвращены Сулейман-шахом.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Адана и Тарс: рубенидское княжество стало Киликийским армянским царством", "de3c4beb"], "d": ["Династия Рубенидов, державшая Адану и Тарс, приняла царский титул; это смена титула той же династии, территория из рук в руки не переходила. День коронации в TDV НЕ НАЙДЕН — дата принята от начала künye Киликийского армянского царства (день künye не является источником).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["Основана Трапезундская греческая империя — Гиресун и Синоп также в её границах", "a99b6ba0"], "d": ["После взятия Константинополя латинянами бежавший в Трапезунд Алексей Комнин провозгласил себя императором; город стал центром нового государства. Государство, основанное внуками Комнина Алексеем и Давидом, простиралось до Синопа; Гиресун также оказался в границах Трапезундской греческой империи.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Кютахья под властью Никейской (Ласкарисов) империи — датированное свидетельство источника", "d91fa405"], "d": ["Источник показывает город Кютахья в эту дату под управлением Никейской (Ласкарисов) империи; более раннее владение в источнике не датировано (атлас оставляет время до этой даты пустым).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["Ильдегизид Абу Бакр взял Мараге", "03faed10"], "d": ["Ахмедилид Алаэддин Кёрпе-Арслан был вынужден оставить крепость Мараге ильдегизидскому атабеку Абу Бакру.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["Сельджуки завоевали Денизли и Хоназ", "1053ccc8"], "d": ["Во второе правление Гийас ад-Дина Кей-Хосрова I Денизли и Хоназ перешли к сельджукам (византийские источники называют 1196 год, статья о сельджуках — 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-07-16:0":{"b": ["Гийас ад-Дин Кей-Хосров I вновь присоединил Мараш к сельджукам", "91b1544e"], "d": ["Кей-Хосров организовал поход против армян и присоединил Мараш к сельджукским землям.", "5ffaa2f3"]},
