"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["Изз ад-Дин Кей-Кавус I завоевал Синоп", "463ea2b9"], "d": ["Сельджукский султан Изз ад-Дин Кей-Кавус I взял Синоп у трапезундских Комнинов.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Алаэддин Кей-Кубад I взял Калоноркс (Alâiye)", "5a4d6ac2"], "d": ["Крепость Калоноркс к востоку от Антальи была взята сельджуками, перестроена и получила имя Alâiye (статья об Алании называет 1221 год).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Джалал ад-Дин Хорезмшах присоединил Азербайджан", "5b812b99"], "d": ["Джалал ад-Дин Хорезмшах присоединил Азербайджан и Арран к своим землям (региональная фраза).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Джалал ад-Дин Хорезмшах взял Мараге", "a55ec004"], "d": ["Джалал ад-Дин Хорезмшах захватил Мараге и сделал его военным и административным центром в Азербайджане.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Джалал ад-Дин Хорезмшах вошёл в Тебриз", "72904097"], "d": ["Когда атабек Узбек отошёл в Гянджу, Джалал ад-Дин Хорезмшах вошёл в Тебриз, овладел городом и сделал его своим центром.", "43ee9867"]},
