"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["После Мириокефала Византия оставила Дорилей", "24aef255"], "d": ["После поражения при Мириокефале Мануил по договору разрушил укрепления Дорилея и оставил город; турки стали называть его Эскишехир.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Амасья присоединена к сельджукским землям", "cf56b964"], "d": ["Килидж-Арслан II присоединил данишмендидские земли (включая Амасью) к сельджукскому государству.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Братья Асень взяли Северную Болгарию; Византия признала Второе Болгарское государство", "ff0554e9"], "d": ["Братья Пётр и Асень при поддержке половцев вновь взяли Северную Болгарию; миром 1187 года Византия признала Второе Болгарское государство.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["Сербия упрочила власть над Зетой", "794c821d"], "d": ["В 1189 году Сербия упрочила власть над Зетой (включая побережье Котора); Зете был признан особый статус.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Ги де Лузиньян купил Кипр, Никосия стала столицей", "11017aea"], "d": ["Ги де Лузиньян купил остров у тамплиеров и сделал Никосию столицей.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Калоян овладел Варной", "1237fe7f"], "d": ["Болгары под командованием царя Калояна в марте 1201 года взяли Варну у Византии; город оставался в границах Болгарского государства в XIII–XIV веках.", "b60444f8"]},
